CREATE OR REPLACE FUNCTION public.task_source_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.app_settings;u uuid;b uuid;BEGIN SELECT * INTO s FROM public.app_settings WHERE id=1;IF TG_TABLE_NAME='bookings' THEN IF NEW.status='pending' AND NEW.archived_at IS NULL THEN SELECT owner_user_id INTO u FROM public.opportunities WHERE booking_id=NEW.id AND outcome IS NULL ORDER BY created_at DESC LIMIT 1;IF NOT public.task_staff_active(u) THEN u:=public.task_pick_role('leasing_manager');END IF;PERFORM public._task_upsert('booking-contact:'||NEW.id,'تواصل مع العميل','booking_contact',u,NEW.created_at+make_interval(hours=>s.task_response_hours),'booking',NEW.id);END IF;ELSIF TG_TABLE_NAME='opportunities' THEN IF NEW.booking_id IS NOT NULL AND NEW.outcome IS NULL AND public.task_staff_active(NEW.owner_user_id) THEN SELECT id INTO b FROM public.bookings WHERE id=NEW.booking_id AND status='pending';IF b IS NOT NULL THEN PERFORM public._task_upsert('booking-contact:'||b,'تواصل مع العميل','booking_contact',NEW.owner_user_id,(SELECT created_at+make_interval(hours=>s.task_response_hours) FROM public.bookings WHERE id=b),'booking',b);END IF;END IF;IF TG_OP='UPDATE' THEN IF OLD.next_action_at IS DISTINCT FROM NEW.next_action_at OR OLD.outcome IS DISTINCT FROM NEW.outcome OR OLD.stage IS DISTINCT FROM NEW.stage THEN UPDATE public.tasks SET status='done',completed_at=now(),outcome_note='تم تحديث المتابعة من سجل الفرصة',updated_at=now() WHERE entity_type='opportunity' AND entity_id=NEW.id AND type='opportunity_followup' AND status='open';END IF;IF OLD.owner_user_id IS DISTINCT FROM NEW.owner_user_id THEN UPDATE public.tasks SET assignee_user_id=NEW.owner_user_id,updated_at=now() WHERE entity_type='opportunity' AND entity_id=NEW.id AND status='open';END IF;END IF;IF NEW.outcome IS NULL AND NEW.stage<>'won' AND NEW.next_action_at IS NULL THEN u:=NEW.owner_user_id;IF NOT public.task_staff_active(u) THEN u:=public.task_pick_role('leasing_manager');END IF;PERFORM public._task_upsert('opportunity-followup:'||NEW.id||':missing','متابعة الفرصة','opportunity_followup',u,NEW.created_at+make_interval(hours=>s.task_response_hours),'opportunity',NEW.id);END IF;END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.task_installment_balance(_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT x.amount_incl_vat-coalesce((SELECT sum(a.amount_incl_vat) FROM public.receipt_allocations a JOIN public.receipts r ON r.id=a.receipt_id WHERE a.installment_id=x.id AND r.status='verified'),0) FROM public.installments x WHERE x.id=_id $$;
REVOKE ALL ON FUNCTION public.task_installment_balance(uuid) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.generate_time_tasks()'::regprocedure) INTO d;d:=regexp_replace(d,'SELECT i.amount_incl_vat-coalesce\(sum\(a.amount_incl_vat\).*?WHERE a.installment_id=i.id;','SELECT public.task_installment_balance(i.id) INTO remaining;','s');d:=replace(d,'public.task_pick_role(''leasing_manager''),now(),''contract'',i.contract_id','public.task_pick_role(''leasing_manager''),(i.due_date+s.grace_days+1)::timestamp AT TIME ZONE ''Asia/Riyadh'',''contract'',i.contract_id');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.task_daily_summary() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;d date:=(now() AT TIME ZONE 'Asia/Riyadh')::date;cnt integer:=0;BEGIN IF auth.role()<>'service_role' AND current_user<>'postgres' AND NOT public.has_permission('tasks.manage','edit') THEN RAISE EXCEPTION 'الملخص غير مسموح';END IF;IF NOT(SELECT task_telegram_enabled FROM public.app_settings WHERE id=1) THEN RETURN 0;END IF;FOR r IN SELECT DISTINCT user_id FROM public.telegram_subscribers WHERE user_id IS NOT NULL AND subscriptions @> ARRAY['daily_summary']::text[] AND (muted_until IS NULL OR muted_until<now()) LOOP IF public.task_staff_active(r.user_id) THEN INSERT INTO public.notification_outbox(user_id,kind,source_key) VALUES(r.user_id,'daily','daily:'||r.user_id||':'||d) ON CONFLICT DO NOTHING;cnt:=cnt+1;END IF;END LOOP;RETURN cnt;END $$;
REVOKE ALL ON FUNCTION public.task_daily_summary() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.task_daily_summary() TO authenticated,service_role;
SELECT to_regprocedure('public.task_installment_balance(uuid)') IS NOT NULL AS balance_ready;